REVOKE ALL ON TABLE public.inspections, public.properties FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.inspections, public.properties TO authenticated;
GRANT ALL ON TABLE public.inspections, public.properties TO service_role;
ALTER TABLE public.inspections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public delete on inspections" ON public.inspections;
DROP POLICY IF EXISTS "Allow public select on inspections" ON public.inspections;
DROP POLICY IF EXISTS "Allow public update on inspections" ON public.inspections;
DROP POLICY IF EXISTS "Allow public insert on inspections" ON public.inspections;
CREATE POLICY "Owners can read inspections" ON public.inspections FOR SELECT TO authenticated USING ((SELECT auth.uid())::text = user_id);
CREATE POLICY "Owners can create inspections" ON public.inspections FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid())::text = user_id);
CREATE POLICY "Owners can update inspections" ON public.inspections FOR UPDATE TO authenticated USING ((SELECT auth.uid())::text = user_id) WITH CHECK ((SELECT auth.uid())::text = user_id);
CREATE POLICY "Owners can delete inspections" ON public.inspections FOR DELETE TO authenticated USING ((SELECT auth.uid())::text = user_id);
DROP POLICY IF EXISTS "Allow public delete on properties" ON public.properties;
DROP POLICY IF EXISTS "Allow public select on properties" ON public.properties;
DROP POLICY IF EXISTS "Allow public update on properties" ON public.properties;
DROP POLICY IF EXISTS "Allow public insert on properties" ON public.properties;
CREATE POLICY "Signed-in users can read properties" ON public.properties FOR SELECT TO authenticated USING ((SELECT auth.uid()) IS NOT NULL);
CREATE POLICY "Signed-in users can create properties" ON public.properties FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) IS NOT NULL);
CREATE POLICY "Signed-in users can update properties" ON public.properties FOR UPDATE TO authenticated USING ((SELECT auth.uid()) IS NOT NULL) WITH CHECK ((SELECT auth.uid()) IS NOT NULL);
CREATE POLICY "Signed-in users can delete properties" ON public.properties FOR DELETE TO authenticated USING ((SELECT auth.uid()) IS NOT NULL);